import { Effect, Schema } from "effect";
import { AnthropicMessages } from "../protocols/anthropic-messages.js";
import { OpenAIChat } from "../protocols/openai-chat.js";
import { OpenResponses } from "../protocols/open-responses.js";
import { OpenAIDecisions } from "../protocols/openai-decisions.js";
import { OpenAIEmbeddings } from "../protocols/openai-embeddings.js";
import { OpenAIImages } from "../protocols/openai-images.js";
import { XAIImages } from "../protocols/xai-images.js";
import { ProviderShared } from "../protocols/shared.js";
import { gatewayProtocol } from "../protocols/utils/gateway-protocol.js";
import { Route } from "../route/client.js";
import { Endpoint } from "../route/endpoint.js";
import { Framing } from "../route/framing.js";
import { MediaRoute } from "../route/media.js";
import { ModelID, ProviderID, ProviderMetadata, ReasoningEffort, } from "../schema/index.js";
import { bearerRouteDefaults, toConfig } from "./settings.js";
export const id = ProviderID.make("vercel-ai-gateway");
const baseURL = "https://ai-gateway.vercel.sh/v1";
const GatewayOptionsSchema = Schema.Struct({
    gateway: Schema.optional(Schema.Record(Schema.String, Schema.Unknown)),
    upstream: Schema.optional(ProviderMetadata),
    reasoningEffort: Schema.optional(ReasoningEffort),
    thinking: Schema.optional(Schema.Struct({
        type: Schema.String,
        budgetTokens: Schema.optional(Schema.Number),
        budget_tokens: Schema.optional(Schema.Number),
    })),
    cacheTTL: Schema.optional(Schema.String),
    cacheAnchorItems: Schema.optional(Schema.Number),
});
const decodeOptions = ProviderShared.validateWith(Schema.decodeUnknownEffect(GatewayOptionsSchema));
const prepare = (api) => Effect.fnUntraced(function* (request) {
    const options = yield* decodeOptions(request.providerOptions ?? {});
    const providerOptions = (() => {
        if (!options.upstream && !options.gateway)
            return undefined;
        if (!options.gateway)
            return options.upstream;
        return { ...options.upstream, gateway: options.gateway };
    })();
    switch (api) {
        case "messages": {
            const effort = options.reasoningEffort;
            if (effort === undefined)
                return { request, body: { providerOptions } };
            const enabled = effort !== "none";
            const thinking = request.providerOptions?.thinking ?? { type: enabled ? "adaptive" : "disabled" };
            const next = {
                ...request,
                providerOptions: {
                    ...request.providerOptions,
                    effort: enabled ? effort : undefined,
                    thinking,
                },
            };
            return { request: next, body: { providerOptions } };
        }
        case "responses":
            return {
                request,
                body: {
                    providerOptions,
                    cache_ttl: options.cacheTTL,
                    cache_anchor_items: options.cacheAnchorItems,
                },
            };
        case "chat": {
            if (!options.thinking)
                return { request, body: { providerOptions } };
            const reasoning = {
                enabled: options.thinking.type !== "disabled",
                max_tokens: options.thinking.budgetTokens ?? options.thinking.budget_tokens,
            };
            return { request, body: { providerOptions, reasoning } };
        }
    }
});
const route = (input) => Route.make({
    id: input.id,
    provider: id,
    providerMetadataKey: id,
    protocol: gatewayProtocol(input.protocol, { id: input.id, prepare: prepare(input.api) }),
    endpoint: Endpoint.path(input.path, { baseURL }),
    framing: input.framing,
    headers: ({ request }) => request.promptCacheKey ? { "x-session-affinity": request.promptCacheKey } : {},
    options: input.options,
});
const messagesRoute = route({
    id: "vercel-ai-gateway-messages",
    protocol: AnthropicMessages.protocol,
    api: "messages",
    path: "/messages",
    framing: AnthropicMessages.framing,
    options: { headers: { "anthropic-version": "2023-06-01" } },
});
const responsesRoute = route({
    id: "vercel-ai-gateway-responses",
    protocol: OpenResponses.protocol,
    api: "responses",
    path: "/responses",
    framing: Framing.sse,
    options: { providerOptions: { store: false, include: ["reasoning.encrypted_content"] } },
});
const chatRoute = route({
    id: "vercel-ai-gateway-chat",
    protocol: OpenAIChat.protocol,
    api: "chat",
    path: "/chat/completions",
    framing: OpenAIChat.framing,
});
export const routes = [messagesRoute, responsesRoute, chatRoute];
// The Gateway passes `size` through to most image models, but Grok ignores it and renders 1024x1024; it only reads
// sizing from `providerOptions.xai`.
const imageSizing = (request) => {
    if (!/^(spacexai|xai)\//.test(request.model.id))
        return OpenAIImages.pixelSize(request);
    if (request.aspect === undefined && request.resolution === undefined)
        return undefined;
    return { providerOptions: { xai: { aspect_ratio: request.aspect, resolution: XAIImages.resolution(request) } } };
};
export const configure = (input = {}) => {
    const configured = bearerRouteDefaults(input, ["AI_GATEWAY_API_KEY", "VERCEL_OIDC_TOKEN"], baseURL);
    const messages = (modelID) => messagesRoute.with(configured).model({
        id: modelID,
        // Recorded Gateway translations for non-Claude models return thinking with empty signatures.
        compatibility: { requireSignature: modelID.startsWith("anthropic/") },
    });
    const responses = (modelID) => responsesRoute.with(configured).model({ id: modelID });
    const chat = (modelID) => chatRoute
        .with(configured)
        .model({ id: modelID, compatibility: { reasoningField: "reasoning" } });
    // Each family uses the API whose Gateway translation carries its reasoning state across turns.
    const model = (modelID) => {
        if (/^(openai\/gpt-|spacexai\/grok-)/.test(modelID))
            return responses(modelID);
        if (modelID.startsWith("meta/muse-"))
            return chat(modelID);
        return messages(modelID);
    };
    const media = MediaRoute.deployment({ ...input, baseURL: configured.endpoint.baseURL }, configured.auth);
    const image = (modelID, providerOptions) => OpenAIImages.model({ ...media, id: modelID, provider: id, providerOptions, sizing: imageSizing });
    const decisionRoute = OpenAIDecisions.route.with({
        provider: id,
        endpoint: { baseURL: configured.endpoint.baseURL },
        auth: configured.auth,
        headers: input.headers,
        http: input.http,
    });
    const decision = (modelID, providerOptions) => decisionRoute.model({ id: modelID, providerOptions });
    const embeddingRoute = OpenAIEmbeddings.route.with({
        provider: id,
        endpoint: { baseURL: configured.endpoint.baseURL },
        auth: configured.auth,
        headers: input.headers,
        http: input.http,
    });
    const embedding = (modelID, providerOptions) => embeddingRoute.model({ id: modelID, providerOptions });
    return { id, model, messages, responses, chat, image, decision, embedding, configure };
};
export const provider = configure();
export const decision = provider.decision;
export const embedding = provider.embedding;
export const messages = provider.messages;
export const responses = provider.responses;
export const chat = provider.chat;
export const image = provider.image;
export const model = (modelID, settings) => configure(toConfig(settings)).model(modelID);
export const messagesModel = (modelID, settings) => configure(toConfig(settings)).messages(modelID);
export const responsesModel = (modelID, settings) => configure(toConfig(settings)).responses(modelID);
export const chatModel = (modelID, settings) => configure(toConfig(settings)).chat(modelID);
export const imageModel = (modelID, settings) => {
    const input = toConfig(settings);
    return configure(input).image(modelID, input.providerOptions);
};
export const decisionModel = (modelID, settings) => {
    const input = toConfig(settings);
    return configure(input).decision(modelID, input.providerOptions);
};
export const embeddingModel = (modelID, settings) => {
    const input = toConfig(settings);
    return configure(input).embedding(modelID, input.providerOptions);
};
export * as VercelAIGateway from "./vercel-ai-gateway.js";
